<?php
session_start();
if (empty($_SESSION['User_id']) || strtolower((string)($_SESSION['User_role'] ?? '')) !== 'resident') { header('Location: login.php'); exit; }
require_once __DIR__ . '/../config/dashboard.php';
$uid = (int)$_SESSION['User_id'];
$stmt = $conn->prepare('SELECT fname,lname,email,phone,address FROM users WHERE ID=?'); $stmt->bind_param('i',$uid); $stmt->execute(); $user=$stmt->get_result()->fetch_assoc() ?: [];
$stmt = $conn->prepare('SELECT COALESCE(SUM(points_delta),0) AS balance FROM point_transactions WHERE user_id=?'); $stmt->bind_param('i',$uid); $stmt->execute(); $points=(int)$stmt->get_result()->fetch_assoc()['balance'];
$stmt = $conn->prepare('SELECT report_id,category,description,photo_path,location_details,status,created_at FROM waste_reports WHERE user_id=? ORDER BY created_at DESC'); $stmt->bind_param('i',$uid); $stmt->execute(); $reports=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);
$rewards=$conn->query('SELECT reward_id,reward_name,description,points_required,stock_qty FROM rewards WHERE is_active=1 ORDER BY points_required')->fetch_all(MYSQLI_ASSOC);
$stmt=$conn->prepare('SELECT points_delta,remarks,created_at FROM point_transactions WHERE user_id=? ORDER BY created_at DESC LIMIT 20'); $stmt->bind_param('i',$uid); $stmt->execute(); $history=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);
$schedules=$conn->query("SELECT area_purok,schedule_date,start_time,status FROM collection_schedules WHERE schedule_date>=CURDATE() AND status<>'cancelled' ORDER BY schedule_date,start_time LIMIT 30")->fetch_all(MYSQLI_ASSOC);
$stmt=$conn->prepare('SELECT rc.status,rc.points_spent,rc.claimed_at,r.reward_name FROM reward_claims rc JOIN rewards r ON r.reward_id=rc.reward_id WHERE rc.user_id=? ORDER BY rc.claimed_at DESC LIMIT 10');$stmt->bind_param('i',$uid);$stmt->execute();$claims=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);
$notice=dashboard_notice(); $purok=$user['address'] ?? '';
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Resident dashboard – BarangayEcoCare</title><link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Outfit:wght@400;500;600;700&display=swap"><link rel="stylesheet" href="../style/global.css"><link rel="stylesheet" href="../style/dashboard.css"></head><body>
<div class="shell"><aside class="sidebar"><div><a href="../index.php" class="logo">Barangay<b>EcoCare</b></a><p class="ws">Resident workspace</p></div><nav class="nav"><a href="#v1">Home</a><a href="#v2">My reports</a><a href="#v3">Schedule</a><a href="#v4">Rewards</a><a href="#v5">Profile</a></nav><div class="me"><div class="me-info"><span class="avatar"><?=e(strtoupper(substr($user['fname']??'R',0,1)))?></span><div><?=e(($user['fname']??'').' '.($user['lname']??''))?><small>Resident · <?=e($purok)?></small></div></div><a href="logout.php" class="btn">Log out</a></div></aside>
<main class="main"><div class="views"><?php if($notice):?><p class="notice" role="status"><?=e($notice)?></p><?php endif;?>
<section class="view" id="v1"><h1>Welcome, <?=e($user['fname']??'')?></h1><p class="sub">Your account activity and community services.</p><div class="grid g3"><article class="card stat"><small>Available points</small><b><?=number_format($points)?></b></article><article class="card stat"><small>Reports filed</small><b><?=count($reports)?></b></article><article class="card stat"><small>Resolved reports</small><b><?=count(array_filter($reports,fn($r)=>$r['status']==='resolved'))?></b></article></div><article class="card" style="margin-top:var(--gap)"><h2>Recent reports</h2><?php if(!$reports):?><p class="muted">You have not submitted a report yet.</p><?php else:?><ul class="rows"><?php foreach(array_slice($reports,0,5) as $r):?><li><div><strong><?=e($r['category'])?></strong><small><?=e($r['location_details'])?> · <?=e(date('M j, Y',strtotime($r['created_at'])))?></small></div><span class="badge b-<?=e($r['status']==='resolved'?'resolved':($r['status']==='verified'?'progress':'pending'))?>"><?=e(ucfirst($r['status']))?></span></li><?php endforeach;?></ul><?php endif;?></article></section>
<section class="view" id="v2"><h1>Report an issue</h1><p class="sub">Describe a waste concern for barangay staff to review.</p><div class="grid g2" style="align-items:start"><form class="card" action="dashboard-action.php" method="post" enctype="multipart/form-data"><?php dashboard_form_token();?><input type="hidden" name="action" value="submit_report"><input type="hidden" name="section" value="v2"><label class="field"><span>Concern</span><select name="category" required><option value="">Choose a concern</option><?php foreach(['Illegal dumping','Uncollected garbage','Overflowing bin','Clogged canal','Other'] as $category):?><option><?=e($category)?></option><?php endforeach;?></select></label><label class="field"><span>Location</span><input name="location" value="<?=e($purok)?>" placeholder="Purok and nearby landmark" required maxlength="255"></label><label class="field"><span>Details</span><textarea name="description" required maxlength="5000" placeholder="Describe what you saw"></textarea></label><label class="field"><span>Photo evidence (optional, max 5 MB)</span><input type="file" name="photo" accept="image/jpeg,image/png,image/webp"></label><button class="btn btn-primary btn-block">Send report</button></form><article class="card"><h2>My reports</h2><?php if(!$reports):?><p class="muted">No reports submitted.</p><?php else:?><ul class="rows"><?php foreach($reports as $r):?><li><div><strong><?=e($r['category'])?></strong><small><?=e($r['location_details'])?> · <?=e(date('M j, Y',strtotime($r['created_at'])))?></small><?php if($r['photo_path']):?><small><a href="../<?=e($r['photo_path'])?>" target="_blank" rel="noopener">View photo evidence</a></small><?php endif;?></div><span class="badge b-pending"><?=e(ucfirst($r['status']))?></span></li><?php endforeach;?></ul><?php endif;?></article></div></section>
<section class="view" id="v3"><h1>Collection schedule</h1><p class="sub">Upcoming collection dates set by barangay staff.</p><article class="card"><ul class="rows"><?php if(!$schedules):?><li><span class="muted">No upcoming schedules have been posted.</span></li><?php else:foreach($schedules as $s):?><li><div><strong><?=e($s['area_purok'])?></strong><small><?=e(date('D, M j, Y',strtotime($s['schedule_date'])))?><?= $s['start_time']?' · '.e(date('g:i A',strtotime($s['start_time']))):''?></small></div><span class="badge b-<?=e($s['status']==='completed'?'done':'pending')?>"><?=e(ucwords(str_replace('_',' ',$s['status'])))?></span></li><?php endforeach;endif;?></ul></article></section>
<section class="view" id="v4"><h1>Rewards</h1><p class="sub">Available balance: <b class="orange"><?=number_format($points)?></b> points.</p><div class="grid g3"><?php if(!$rewards):?><article class="card"><p class="muted">No active rewards are available yet.</p></article><?php endif;?><?php foreach($rewards as $reward):?><article class="card zone"><h3><?=e($reward['reward_name'])?></h3><p><?=e($reward['description'])?></p><p class="price"><?=number_format((int)$reward['points_required'])?> points · <?=number_format((int)$reward['stock_qty'])?> left</p><?php if((int)$reward['stock_qty']>0 && $points >= (int)$reward['points_required']):?><form action="dashboard-action.php" method="post"><?php dashboard_form_token();?><input type="hidden" name="action" value="claim_reward"><input type="hidden" name="section" value="v4"><input type="hidden" name="reward_id" value="<?=(int)$reward['reward_id']?>"><button class="btn btn-primary btn-block">Request reward</button></form><?php else:?><button class="btn btn-block" disabled><?=((int)$reward['stock_qty']<1)?'Out of stock':'Not enough points'?></button><?php endif;?></article><?php endforeach;?></div><article class="card" style="margin-top:var(--gap)"><h2>Points history</h2><ul class="rows"><?php if(!$history):?><li><span class="muted">No point transactions yet.</span></li><?php else:foreach($history as $tx):?><li><div><strong><?=e($tx['remarks'])?></strong><small><?=e(date('M j, Y',strtotime($tx['created_at'])))?></small></div><b class="<?=((int)$tx['points_delta']>=0?'plus':'orange')?>"><?=((int)$tx['points_delta']>0?'+':'')?><?=number_format((int)$tx['points_delta'])?></b></li><?php endforeach;endif;?></ul><h2>Reward requests</h2><ul class="rows"><?php if(!$claims):?><li><span class="muted">No reward requests.</span></li><?php else:foreach($claims as $claim):?><li><div><strong><?=e($claim['reward_name'])?></strong><small><?=number_format((int)$claim['points_spent'])?> points · <?=e(date('M j, Y',strtotime($claim['claimed_at'])))?></small></div><span class="badge b-pending"><?=e(ucfirst($claim['status']))?></span></li><?php endforeach;endif;?></ul></article></section>
<section class="view" id="v5"><h1>My profile</h1><div class="grid g2" style="align-items:start"><form class="card" action="dashboard-action.php" method="post"><?php dashboard_form_token();?><input type="hidden" name="action" value="update_profile"><input type="hidden" name="section" value="v5"><label class="field"><span>First name</span><input name="fname" value="<?=e($user['fname']??'')?>" required></label><label class="field"><span>Last name</span><input name="lname" value="<?=e($user['lname']??'')?>" required></label><label class="field"><span>Email</span><input type="email" name="email" value="<?=e($user['email']??'')?>" required></label><label class="field"><span>Phone</span><input name="phone" value="<?=e($user['phone']??'')?>"></label><label class="field"><span>Purok / address</span><input name="address" value="<?=e($purok)?>"></label><button class="btn btn-primary">Save profile</button></form><form class="card" action="dashboard-action.php" method="post"><?php dashboard_form_token();?><input type="hidden" name="action" value="change_password"><input type="hidden" name="section" value="v5"><label class="field"><span>New password</span><input type="password" name="password" minlength="8" required></label><label class="field"><span>Confirm password</span><input type="password" name="confirm" minlength="8" required></label><button class="btn btn-primary">Change password</button></form></div></section>
</div></main></div></body></html>
